{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Ketoconazole, the closest analogue sharing the dichlorophenyl-dioxolane-piperazine-phenyl ether core, has 76% oral bioavailability in humans, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Posaconazole, a close analogue with the same triazolone-piperazine-phenyl ether scaffold, showed 42% oral bioavailability in fasted Chinese volunteers receiving a tablet, directly relevant to the fasted-state query and above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Voriconazole, another azole antifungal, exceeds 90% oral bioavailability in the fasted state, supporting high oral absorption for this azole class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Posaconazole oral suspension had an absolute bioavailability of 16.5% in pediatric patients, below the threshold, but this is formulation- and population-specific and has limited transferability to the query as an unformulated molecular property.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Venetoclax showed 5.4% absolute bioavailability under fasting conditions, but this BCL-2 inhibitor is structurally unrelated to the azole scaffold and provides only weak, low-transferability contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high oral bioavailability (F ≥20%) based on strong transferable evidence from ketoconazole (76% human F) and posaconazole (42-56% fasted tablet F), both sharing the query's azole-dichlorophenyl-dioxolane-piperazine scaffold; the only low-F evidence is formulation-specific or structurally unrelated with low transferability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "Fasted-state bioavailability for the query's exact formulation is unknown; posaconazole suspension can have low F in pediatric patients.",
    "The low-F venetoclax evidence comes from a different chemotype and is not transferable to this azole antifungal scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

